from decimal import Decimal, ROUND_HALF_UP
from typing import Any


_CENTS = Decimal("0.01")
_HUNDRED = Decimal("100")


def _decimal(value: Any) -> Decimal:
    """Implement legacy NVL(value, 0) numeric coercion for supported inputs."""
    if value is None or value == "":
        return Decimal(0)
    if isinstance(value, Decimal):
        return value
    # str() preserves user-supplied decimal text and avoids binary float arithmetic.
    return Decimal(str(value))


def _round_cents(value: Decimal) -> Decimal:
    return value.quantize(_CENTS, rounding=ROUND_HALF_UP)


def recompute(order: dict, lines: list[dict]) -> tuple[dict, list[dict], list]:
    """
    Recompute live line extensions and the discounted order total.

    Inputs are not mutated. Returned lines retain input order and include copies of
    soft-deleted lines without changing their stored extension amounts.
    """
    new_order = dict(order)
    new_lines = [dict(line) for line in lines]

    if order.get("DEL_FLG") == "Y" or order.get("STAT_CD") == "X":
        return new_order, new_lines, []

    total = Decimal(0)

    for source_line, new_line in zip(lines, new_lines):
        if source_line.get("DEL_FLG") == "Y":
            continue

        extension = _round_cents(
            _decimal(source_line.get("QTY", 0))
            * _decimal(source_line.get("UNIT_PRC", 0))
        )
        new_line["EXT_AMT"] = float(extension)
        total += extension

    discounted = _round_cents(
        total
        * (_HUNDRED - _decimal(order.get("DISC_PCT", 0)))
        / _HUNDRED
    )

    if _decimal(order.get("TOT_AMT", 0)) != discounted:
        new_order["TOT_AMT"] = float(discounted)
        return new_order, new_lines, [("ORD_RETOTAL", order.get("ORD_ID"))]

    return new_order, new_lines, []
